TemplateResponse::Conversion_report_time_typeEnum TemplateResponse::toConversion_report_time_typeEnum(const utility::string_t& value) const
{
    
    if (value == utility::conversions::to_string_t("TIME_OF_AD_ACTION")) {
        return Conversion_report_time_typeEnum::TIME_OF_AD_ACTION;
    }
    
    if (value == utility::conversions::to_string_t("TIME_OF_CONVERSION")) {
        return Conversion_report_time_typeEnum::TIME_OF_CONVERSION;
    }
    
    throw std::invalid_argument("Invalid value for conversion to Conversion_report_time_typeEnum");
}


const utility::string_t TemplateResponse::fromConversion_report_time_typeEnum(const Conversion_report_time_typeEnum value) const
{
    switch(value)
    {
        
        case Conversion_report_time_typeEnum::TIME_OF_AD_ACTION: return utility::conversions::to_string_t("TIME_OF_AD_ACTION");
        
        case Conversion_report_time_typeEnum::TIME_OF_CONVERSION: return utility::conversions::to_string_t("TIME_OF_CONVERSION");
        
    }
}

